arguments.command:
cat << 'EOF' > /app/output/temp_poster.html
<!DOCTYPE html>
<html lang="en" class="theme-dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Mapping Neural Circuit Architecture</title>
  <link href="/app/libs/fonts/inter.css" rel="stylesheet">
  <script src="/app/libs/chart.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root { interpolate-size: allow-keywords; }

    /* ===== THEMES ===== */
    html.theme-dark {
      --bg: #0b1120;
      --surface: #151e32;
      --surface-hover: #1e293b;
      --border: rgba(255,255,255,0.08);
      --text: #f8fafc;
      --text-secondary: #94a3b8;
      --accent: #0ea5e9;
      --accent-secondary: #14b8a6;
      --positive: #fbbf24;
      --negative: #f43f5e;
      --warning: #f59e0b;
    }
    html.theme-light {
      --bg: #f8fafc;
      --surface: #ffffff;
      --surface-hover: #f1f5f9;
      --border: rgba(0,0,0,0.08);
      --text: #0f172a;
      --text-secondary: #475569;
      --accent: #0284c7;
      --accent-secondary: #0d9488;
      --positive: #d97706;
      --negative: #e11d48;
      --warning: #d97706;
    }

    body {
      font-family: 'Inter', -apple-system, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.6; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em;
      width: 1414px; height: 2000px;
      overflow: hidden;
      display: flex; flex-direction: column;
    }

    h1,h2,h3,h4,h5,h6 { 
      color: var(--text); 
      letter-spacing: -0.03em; 
      line-height: 1.1;
      text-wrap: balance;
    }
    h1 { font-weight: 800; font-size: 72px; margin-bottom: 24px; background: linear-gradient(135deg, var(--text), var(--accent-secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
    h2 { font-weight: 700; font-size: 42px; margin-bottom: 32px; color: var(--accent); display: flex; align-items: center; gap: 16px; }
    h2::before { content: ""; display: block; width: 8px; height: 42px; background: var(--positive); border-radius: 4px; }
    h3 { font-weight: 600; font-size: 28px; margin-bottom: 16px; color: var(--text); }
    body, p, li, td, th, span, label { font-weight: 400; font-size: 22px; }
    p { margin-bottom: 24px; color: var(--text-secondary); line-height: 1.7; }

    .card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 16px; padding: 40px;
      display: flex; flex-direction: column;
      height: 100%;
    }

    /* Poster Layout */
    .poster-header {
      padding: 60px 80px 40px;
      border-bottom: 1px solid var(--border);
      background: linear-gradient(180deg, rgba(14, 165, 233, 0.05) 0%, rgba(14, 165, 233, 0) 100%);
    }
    .poster-subtitle {
      font-size: 32px; color: var(--text-secondary); max-width: 1100px; font-weight: 500; line-height: 1.4;
    }
    .venue-badge {
      display: inline-block; padding: 12px 24px; background: rgba(251, 191, 36, 0.15); 
      color: var(--positive); border: 1px solid rgba(251, 191, 36, 0.3);
      border-radius: 50px; font-size: 20px; font-weight: 600; margin-bottom: 32px;
      letter-spacing: 0.05em; text-transform: uppercase;
    }

    .poster-body {
      flex: 1; display: flex; flex-direction: column;
      padding: 40px 80px; gap: 40px;
    }

    /* Metrics Strip */
    .metrics-strip {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px;
    }
    .metric-card {
      background: var(--surface); border: 1px solid var(--border); border-radius: 16px;
      padding: 32px 24px; text-align: center; position: relative; overflow: hidden;
    }
    .metric-card::after {
      content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; background: var(--accent);
    }
    .metric-card:nth-child(2)::after { background: var(--accent-secondary); }
    .metric-card:nth-child(3)::after { background: var(--positive); }
    .metric-card:nth-child(4)::after { background: var(--accent); }
    .metric-card:nth-child(5)::after { background: var(--text-secondary); }

    .metric-value { font-size: 48px; font-weight: 800; color: var(--text); margin-bottom: 12px; line-height: 1; }
    .metric-label { font-size: 20px; font-weight: 600; color: var(--accent); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 12px; }
    .metric-context { font-size: 16px; color: var(--text-secondary); line-height: 1.4; }

    /* Main Grid */
    .main-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 40px; flex: 1;
    }

    .col-left { display: flex; flex-direction: column; gap: 40px; }
    .col-right { display: flex; flex-direction: column; gap: 40px; }

    /* Pipeline Methods */
    .pipeline-grid { display: grid; grid-template-columns: 1fr; gap: 16px; margin-top: 24px; }
    .pipeline-step { 
      display: flex; align-items: center; gap: 24px; 
      background: rgba(255,255,255,0.03); padding: 20px 24px; border-radius: 12px;
      border: 1px solid var(--border);
    }
    .step-num { 
      width: 48px; height: 48px; border-radius: 50%; background: var(--accent-secondary); 
      color: #fff; display: flex; align-items: center; justify-content: center; 
      font-size: 24px; font-weight: 700; flex-shrink: 0;
    }
    .step-text h4 { font-size: 22px; margin-bottom: 4px; color: var(--text); }
    .step-text p { margin: 0; font-size: 18px; color: var(--text-secondary); }

    /* Findings Grid inside Key Findings */
    .findings-list { margin-top: 24px; display: flex; flex-direction: column; gap: 24px; }
    .finding-item { display: flex; gap: 24px; align-items: flex-start; }
    .finding-icon { 
      width: 40px; height: 40px; flex-shrink: 0; color: var(--positive);
      background: rgba(251,191,36,0.1); border-radius: 8px; display: flex; align-items: center; justify-content: center;
    }
    .finding-icon svg { width: 24px; height: 24px; }
    .finding-text h4 { font-size: 24px; color: var(--text); margin-bottom: 8px; }
    .finding-text p { margin: 0; font-size: 20px; color: var(--text-secondary); }

    .charts-container {
      display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 40px; flex: 1; min-height: 360px;
    }
    .chart-box {
      background: rgba(0,0,0,0.2); border: 1px solid var(--border); border-radius: 12px; padding: 24px;
      display: flex; flex-direction: column;
    }
    .chart-title { font-size: 20px; text-align: center; margin-bottom: 16px; font-weight: 600; color: var(--text); }
    .chart-container { flex: 1; position: relative; min-height: 250px; }

    /* Implications */
    .implications-card { background: linear-gradient(135deg, var(--surface), rgba(14,165,233,0.1)); }

    /* Animations */
    .animate { animation: fadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) both; }
    .delay-1 { animation-delay: 0.1s; }
    .delay-2 { animation-delay: 0.2s; }
    .delay-3 { animation-delay: 0.3s; }
    .delay-4 { animation-delay: 0.4s; }
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(40px); } to { opacity: 1; transform: translateY(0); } }

  </style>
</head>
<body>
  <div class="poster-header animate">
    <div class="venue-badge">Nature Research Conference / Neuroscience Symposium</div>
    <h1>Mapping Neural Circuit Architecture: Advances in Brain Connectivity Analysis</h1>
    <div class="poster-subtitle">A comprehensive study published in Nature (2024) reveals new principles of neural circuit organization through large-scale connectomics and functional mapping.</div>
  </div>

  <div class="poster-body">
    <!-- Metrics Strip -->
    <div class="metrics-strip animate delay-1">
      <div class="metric-card">
        <div class="metric-value">~125K</div>
        <div class="metric-label">Neurons Mapped</div>
        <div class="metric-context">Total neurons reconstructed in dataset</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">~54M</div>
        <div class="metric-label">Synaptic Connections</div>
        <div class="metric-context">Individual synapses catalogued</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">37</div>
        <div class="metric-label">Circuit Motifs</div>
        <div class="metric-context">Distinct recurring connectivity motifs</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">94.2%</div>
        <div class="metric-label">Classification Accuracy</div>
        <div class="metric-context">Automated neuron-type performance</div>
      </div>
      <div class="metric-card" style="background: rgba(255,255,255,0.03);">
        <div class="metric-value" style="font-size: 36px; padding: 6px 0;">Nature</div>
        <div class="metric-label">2024 Publication</div>
        <div class="metric-context">DOI: 10.1038/s41586-024-07487-w</div>
      </div>
    </div>

    <!-- Main Content -->
    <div class="main-grid">
      <!-- Left Column -->
      <div class="col-left">
        <!-- Background -->
        <div class="card animate delay-2">
          <h2>Background & Motivation</h2>
          <p>Understanding how the brain processes information requires detailed maps of neural connectivity. While classical neuroanatomy provided foundational insights, the field has long lacked the resolution and scale needed to capture complete circuit-level wiring diagrams.</p>
          <p style="margin:0;">Recent advances in electron microscopy, automated segmentation, and computational neuroscience have converged to make large-scale connectomics feasible, bridging the gap between structural connectivity and functional organization.</p>
        </div>

        <!-- Methods -->
        <div class="card animate delay-3" style="flex:1;">
          <h2>Methodology & Approach</h2>
          <p>A multi-modal pipeline combining serial-section electron microscopy with advanced machine learning for automated neuron reconstruction.</p>
          <div class="pipeline-grid">
            <div class="pipeline-step">
              <div class="step-num">1</div>
              <div class="step-text">
                <h4>Imaging Modality</h4>
                <p>Serial-section electron microscopy at 4×4×30 nm resolution</p>
              </div>
            </div>
            <div class="pipeline-step">
              <div class="step-num">2</div>
              <div class="step-text">
                <h4>Segmentation Pipeline</h4>
                <p>Deep learning-based automated tracing with human proofreading</p>
              </div>
            </div>
            <div class="pipeline-step">
              <div class="step-num">3</div>
              <div class="step-text">
                <h4>Synapse Detection</h4>
                <p>Convolutional neural network classifier (94.2% accuracy)</p>
              </div>
            </div>
            <div class="pipeline-step">
              <div class="step-num">4</div>
              <div class="step-text">
                <h4>Functional Validation</h4>
                <p>Calcium imaging and optogenetic perturbation experiments</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- Right Column -->
      <div class="col-right">
        <!-- Findings -->
        <div class="card animate delay-2" style="flex: 2;">
          <h2>Key Findings</h2>
          <div class="findings-list">
            <div class="finding-item">
              <div class="finding-icon">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
              </div>
              <div class="finding-text">
                <h4>37 Distinct Connectivity Motifs</h4>
                <p>Recurring building blocks of larger circuits suggesting a modular wiring logic, analogous to logic gates.</p>
              </div>
            </div>
            <div class="finding-item">
              <div class="finding-icon">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9"></path></svg>
              </div>
              <div class="finding-text">
                <h4>Hub Neuron Dominance</h4>
                <p>Highly non-uniform distribution of influence: ~3.5% of neurons account for over 28% of total synaptic output.</p>
              </div>
            </div>
            <div class="finding-item">
              <div class="finding-icon">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
              </div>
              <div class="finding-text">
                <h4>Layer & Cell-Type Specificity</h4>
                <p>Recurrent connections enriched within L5 (4.7:1 ratio). Inhibitory interneurons show 6.2× higher specificity than excitatory neurons.</p>
              </div>
            </div>
          </div>

          <div class="charts-container">
            <div class="chart-box" role="img" aria-label="Donut chart showing synaptic output share: Hub Neurons 28%, Other 72%">
              <div class="chart-title">Synaptic Output Share</div>
              <div class="chart-container">
                <canvas id="hubChart"></canvas>
              </div>
            </div>
            <div class="chart-box" role="img" aria-label="Bar chart showing wiring specificity multiplier">
              <div class="chart-title">Wiring Specificity (Multiplier)</div>
              <div class="chart-container">
                <canvas id="specChart"></canvas>
              </div>
            </div>
          </div>
        </div>

        <!-- Implications -->
        <div class="card implications-card animate delay-4">
          <h2>Implications & Future Directions</h2>
          <p>These findings reshape our understanding of cortical computation. The discovery of modular connectivity motifs suggests that the brain employs a finite vocabulary of circuit elements. The identification of hub neurons as disproportionate drivers of network activity has direct implications for understanding how focal lesions or targeted stimulation can produce widespread effects — critical for both neurological disease treatment and brain-computer interface design.</p>
          <p style="margin:0; font-weight: 500; color: var(--accent-secondary);">Future work will extend this connectomic approach to additional brain regions, with the ultimate goal of building a complete mammalian brain wiring diagram.</p>
        </div>
      </div>
    </div>
  </div>

  <script>
    Chart.defaults.animation = false;
    Chart.defaults.color = '#94a3b8';
    Chart.defaults.font.family = 'Inter';
    Chart.defaults.font.size = 14;

    function buildCharts() {
      // Hub Chart
      var ctx1 = document.getElementById('hubChart');
      if (ctx1) {
        new Chart(ctx1, {
          type: 'doughnut',
          data: {
            labels: ['Hub Neurons (3.5% of pop)', 'Other Neurons (96.5%)'],
            datasets: [{
              data: [28, 72],
              backgroundColor: ['#fbbf24', 'rgba(255,255,255,0.1)'],
              borderWidth: 0,
              hoverOffset: 4
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '65%',
            plugins: {
              legend: { position: 'bottom', labels: { padding: 20, color: '#f8fafc' } },
              tooltip: { enabled: true, padding: 12, cornerRadius: 8 }
            }
          }
        });
      }

      // Specificity Chart
      var ctx2 = document.getElementById('specChart');
      if (ctx2) {
        new Chart(ctx2, {
          type: 'bar',
          data: {
            labels: ['Excitatory', 'Inhibitory (Interneurons)'],
            datasets: [{
              label: 'Specificity Multiplier',
              data: [1.0, 6.2],
              backgroundColor: ['rgba(14, 165, 233, 0.3)', '#14b8a6'],
              borderRadius: 6
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
              y: { 
                beginAtZero: true, 
                grid: { color: 'rgba(255,255,255,0.05)' },
                ticks: { color: '#94a3b8' }
              },
              x: { 
                grid: { display: false },
                ticks: { color: '#f8fafc', font: { size: 16 } }
              }
            },
            plugins: {
              legend: { display: false },
              tooltip: { enabled: true, padding: 12, cornerRadius: 8 }
            }
          }
        });
      }
    }

    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
</body>
</html>
EOF
